#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <shared_mutex>
#include <atomic>
#include <cstring>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>
#include <algorithm>

class SessionStore {
public:
    struct Session {
        std::string token;
        std::string username;
        int privilege_level;
        std::vector<uint8_t> data;
    };

    // Returns a COPY of the session (safe against invalidation)
    std::pair<bool, Session> lookup(const std::string& token) {
        auto it = sessions_.find(token);
        if (it == sessions_.end()) return {false, {}};
        return {true, it->second};
    }

    // Creates or updates a session
    void upsert(const std::string& token, const Session& s) {
        sessions_[token] = s;
    }

    void remove(const std::string& token) {
        sessions_.erase(token);
    }

    size_t count() const { return sessions_.size(); }

    std::shared_mutex& mutex() { return mtx_; }

private:
    std::unordered_map<std::string, Session> sessions_;
    mutable std::shared_mutex mtx_;
};

class RequestHandler {
public:
    RequestHandler(SessionStore& store) : store_(store) {}

    std::string authenticate(const std::string& token, const std::string& action) {
        // Validate session and check privilege atomically under one lock
        std::shared_lock<std::shared_mutex> lock(store_.mutex());
        auto [found, session] = store_.lookup(token);
        if (!found) {
            return "ERR:INVALID_SESSION";
        }
        if (session.privilege_level < required_privilege(action)) {
            return "ERR:INSUFFICIENT_PRIVILEGE";
        }
        return execute_action(session, action);
    }

    // This is the admin endpoint - handles session management
    std::string admin_operation(const std::string& admin_token, 
                                const std::string& target_token,
                                const std::string& operation) {
        if (operation == "elevate") {
            // Use exclusive lock for the entire read-modify-write
            std::unique_lock<std::shared_mutex> wlock(store_.mutex());
            auto [admin_found, admin_session] = store_.lookup(admin_token);
            if (!admin_found || admin_session.privilege_level < 9) {
                return "ERR:NOT_ADMIN";
            }

            auto [target_found, target] = store_.lookup(target_token);
            if (!target_found) {
                return "ERR:TARGET_NOT_FOUND";
            }

            // Use CURRENT privilege level (from the copy just obtained)
            target.privilege_level = target.privilege_level + 1;
            store_.upsert(target_token, target);
            return "OK:ELEVATED:" + target.username;
        }

        if (operation == "inspect") {
            std::shared_lock<std::shared_mutex> rlock(store_.mutex());
            auto [admin_found, admin_session] = store_.lookup(admin_token);
            if (!admin_found || admin_session.privilege_level < 9) {
                return "ERR:NOT_ADMIN";
            }
            auto [target_found, target] = store_.lookup(target_token);
            if (!target_found) {
                return "ERR:TARGET_NOT_FOUND";
            }
            return "OK:PRIV=" + std::to_string(target.privilege_level) + 
                   ":USER=" + target.username;
        }

        return "ERR:UNKNOWN_OP";
    }

    // Cleanup expired sessions - runs in background thread
    void cleanup_expired(const std::vector<std::string>& expired_tokens) {
        std::unique_lock<std::shared_mutex> lock(store_.mutex());
        for (const auto& token : expired_tokens) {
            store_.remove(token);
        }
    }

    // Bulk import sessions - called during startup or migration
    void bulk_import(const std::vector<SessionStore::Session>& new_sessions) {
        std::unique_lock<std::shared_mutex> lock(store_.mutex());
        for (const auto& s : new_sessions) {
            store_.upsert(s.token, s);
        }
    }

private:
    int required_privilege(const std::string& action) {
        if (action == "read") return 1;
        if (action == "write") return 3;
        if (action == "admin") return 9;
        return 99;
    }

    std::string execute_action(const SessionStore::Session& s, 
                               const std::string& action) {
        if (action == "read") {
            return "OK:DATA_SIZE=" + std::to_string(s.data.size());
        }
        if (action == "write") {
            return "OK:WRITTEN:" + s.username;
        }
        return "ERR:UNHANDLED";
    }

    SessionStore& store_;
};

// Network layer - parses binary protocol
struct PacketHeader {
    uint16_t version;
    uint16_t cmd;
    uint32_t body_length;
};

class Server {
public:
    Server(int port) : port_(port), running_(false), handler_(store_) {}

    void start() {
        running_ = true;
        int server_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd < 0) return;

        int opt = 1;
        setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

        struct sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(port_);

        if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            close(server_fd);
            return;
        }
        listen(server_fd, 128);

        while (running_) {
            struct sockaddr_in client_addr{};
            socklen_t client_len = sizeof(client_addr);
            int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
            if (client_fd < 0) continue;

            // Handle each client in a new thread
            std::thread([this, client_fd]() {
                handle_client(client_fd);
                close(client_fd);
            }).detach();
        }
        close(server_fd);
    }

private:
    void handle_client(int fd) {
        char buf[4096];

        // Read header
        ssize_t n = read(fd, buf, sizeof(PacketHeader));
        if (n < (ssize_t)sizeof(PacketHeader)) return;

        PacketHeader hdr;
        memcpy(&hdr, buf, sizeof(PacketHeader));

        if (hdr.version != 1) return;
        if (hdr.body_length > sizeof(buf) - sizeof(PacketHeader) - 1) return;

        // Read body
        size_t total_read = 0;
        while (total_read < hdr.body_length) {
            n = read(fd, buf + sizeof(PacketHeader) + total_read, 
                     hdr.body_length - total_read);
            if (n <= 0) return;
            total_read += (size_t)n;
        }

        // Parse body as null-terminated strings
        char* body = buf + sizeof(PacketHeader);
        body[hdr.body_length] = '\0';

        std::string token(body);
        char* next = body + token.size() + 1;
        if (next >= body + hdr.body_length) return;
        std::string param1(next);

        std::string response;
        switch (hdr.cmd) {
            case 1: // authenticate
                response = handler_.authenticate(token, param1);
                break;
            case 2: { // admin op
                char* next2 = next + param1.size() + 1;
                if (next2 >= body + hdr.body_length) return;
                std::string param2(next2);
                response = handler_.admin_operation(token, param1, param2);
                break;
            }
            case 3: { // create session
                SessionStore::Session s;
                s.token = token;
                s.username = param1;
                s.privilege_level = 1;
                std::unique_lock<std::shared_mutex> lock(store_.mutex());
                store_.upsert(token, s);
                response = "OK:CREATED";
                break;
            }
            default:
                response = "ERR:UNKNOWN_CMD";
        }

        write(fd, response.c_str(), response.size());
    }

    int port_;
    std::atomic<bool> running_;
    SessionStore store_;
    RequestHandler handler_;
};

int main(int argc, char* argv[]) {
    int port = 8080;
    if (argc > 1) port = std::atoi(argv[1]);
    Server server(port);
    server.start();
    return 0;
}
